import { compileArrivalProjection } from '../../tenants/arrival-projection-engine.js';
import { escapeHtml, safeColor, tags } from './template-helpers.js';

const signed = value => value > 0 ? `+${value}` : String(value);

export function renderArrivalProjection(state, buildingId, spaceId, candidate) {
  const projection = compileArrivalProjection(state, buildingId, spaceId, candidate);
  if (!projection) return '';
  const visual = projection.spaceVisual;
  const roommates = projection.roommates.length ? projection.roommates.map(person => `<i style="--roommate-color:${safeColor(person.color)}" title="${escapeHtml(`${person.name} · ${person.origin}`)}">${escapeHtml(person.name.slice(0, 1))}</i>`).join('') : '<small>这里还没有其他人物</small>';
  const sparks = projection.sparks.length ? projection.sparks.map(spark => `<p><span>${escapeHtml(spark.otherName)}</span><strong>${escapeHtml(spark.label)}</strong><b>${spark.score}</b></p>`).join('') : '<small>首次入住会在这里留下一个人的第一段生活痕迹。</small>';
  return `<article class="lmo-arrival-projection" data-arrival-projection="${escapeHtml(projection.signature)}" style="--person-accent:${safeColor(projection.candidate.color)};--room-base:${safeColor(visual.css.base)};--room-accent:${safeColor(visual.css.accent)};--room-secondary:${safeColor(visual.css.secondary)}"><header><i>${escapeHtml(projection.candidate.name.slice(0, 1))}</i><div><span>ARRIVAL SIMULATION</span><h3>${escapeHtml(projection.candidate.name)}的入住预演</h3><p>${escapeHtml(`${projection.candidate.origin} · ${projection.candidate.profession} → ${projection.buildingName} / ${projection.spaceName}`)}</p></div><em style="--fit:${projection.fit}"><b>${projection.fit}</b><small>${escapeHtml(projection.fitState)}</small></em></header><div class="lmo-arrival-grid"><section class="lmo-arrival-chamber"><div><span>${escapeHtml(projection.spaceName)}</span><strong>${escapeHtml(visual.style)}</strong></div><b>${escapeHtml(projection.candidate.name.slice(0, 1))}</b><aside>${roommates}</aside></section><section class="lmo-arrival-reading"><span>EMBODIED REACTION</span><blockquote>${escapeHtml(projection.reaction)}</blockquote>${tags([...projection.preferenceTags, ...projection.matchedTags].slice(0, 5))}<div class="lmo-arrival-deltas"><p><b>${signed(projection.pulseDelta.roomVitality)}</b><small>房间活力</small></p><p><b>${signed(projection.pulseDelta.roomTotal)}</b><small>房间脉冲</small></p><p><b>${signed(projection.pulseDelta.vitality)}</b><small>建筑活力</small></p><p><b>${signed(projection.pulseDelta.total)}</b><small>综合脉冲</small></p></div></section><aside class="lmo-arrival-social"><span>POTENTIAL ENCOUNTERS</span>${sparks}${projection.newSynergies.length ? `<em>新协同 · ${escapeHtml(projection.newSynergies.join(' / '))}</em>` : ''}</aside></div><footer>这里只是基于真实空间与现有租客的代码预演；确认加入前不会创建人物、关系或事件。</footer></article>`;
}
