import { compilePortfolioRadar } from '../../buildings/portfolio-radar-engine.js';
import { escapeHtml, safeColor } from './template-helpers.js';
import { renderPortfolioAssignmentMatrix } from './portfolio-assignment-template.js';

const metricLabels = Object.freeze([['comfort', '舒适'], ['function', '功能'], ['vitality', '活力'], ['appeal', '吸引']]);

export function renderPortfolioRadar(state) {
  const radar = compilePortfolioRadar(state);
  const cards = radar.buildings.map(building => `<button class="lmo-radar-card ${building.current ? 'current' : ''}" data-action="open-building" data-building-id="${escapeHtml(building.id)}" data-radar-building="${escapeHtml(building.id)}" style="--radar-accent:${safeColor(building.color)};--pulse:${building.pulse}"><header><div><span>${escapeHtml(building.type)} · ${building.current ? '当前焦点' : building.pulseState}</span><strong>${escapeHtml(building.name)}</strong></div><em><b>${building.pulse}</b><small>综合脉冲</small></em></header><div class="lmo-radar-body"><svg viewBox="0 0 100 100" role="img" aria-label="${escapeHtml(`${building.name}经营雷达`)}"><path d="M50 12 L88 50 L50 88 L12 50 Z"></path><path d="M50 31 L69 50 L50 69 L31 50 Z"></path><line x1="50" y1="8" x2="50" y2="92"></line><line x1="8" y1="50" x2="92" y2="50"></line><polygon points="${building.polygon}"></polygon>${metricLabels.map(([key, label], index) => `<text x="${[50, 93, 50, 7][index]}" y="${[8, 52, 98, 52][index]}">${escapeHtml(`${label} ${building.metrics[key]}`)}</text>`).join('')}</svg><div><p><b>${building.residents}</b><small>人物</small></p><p><b>${building.origins}</b><small>世界</small></p><p><b>${building.emptySpaces}</b><small>空置</small></p><p><b>${building.synergies.length}</b><small>协同</small></p></div></div>${building.focus ? `<footer><span>下一处值得投入 · ${escapeHtml(building.focus.name)} / ${building.focus.score}</span><strong>${escapeHtml(building.focus.action)}</strong></footer>` : ''}</button>`).join('');
  return `<section class="lmo-portfolio-radar" data-portfolio-radar="${escapeHtml(radar.signature)}"><div class="lmo-section-heading compact"><div><span>PORTFOLIO SITUATION ROOM</span><h2>经营态势雷达 · 一眼看懂所有建筑</h2></div><p>只比较已经接管的建筑；数值来自真实装修、设施、用途和人物，不制造账单或失败惩罚。</p></div><div class="lmo-radar-summary"><p><b>${radar.metrics.buildings}</b><small>已接管建筑</small></p><p><b>${radar.metrics.residents}</b><small>版图人物</small></p><p><b>${radar.metrics.origins}</b><small>来源世界</small></p><p><b>${radar.metrics.emptySpaces}</b><small>可塑空间</small></p><p><b>${radar.metrics.activeSynergies}</b><small>活跃协同</small></p><aside><span>最高脉冲</span><strong>${escapeHtml(radar.spotlight?.buildingName ?? '等待建筑')}</strong><small>${radar.spotlight?.pulse ?? 0} · ${escapeHtml(radar.spotlight?.state ?? '等待点亮')}</small></aside></div><div class="lmo-radar-grid">${cards}</div>${radar.focus ? `<div class="lmo-radar-focus"><span>PORTFOLIO FOCUS</span><strong>${escapeHtml(radar.focus.buildingName)} · ${escapeHtml(radar.focus.name)}</strong><p>${escapeHtml(`${radar.focus.label}是当前最有成长余地的维度；建议${radar.focus.action}。这只是爽感导向建议，不是强制任务。`)}</p></div>` : ''}</section>${renderPortfolioAssignmentMatrix(state)}`;
}
