import { compileAcquisitionProjection } from '../../buildings/acquisition-projection-engine.js';
import { escapeHtml, safeColor, tags } from './template-helpers.js';

const signed = value => value > 0 ? `+${value}` : String(value);

export function renderAcquisitionProjection(state, buildingId, direction) {
  const projection = compileAcquisitionProjection(state, buildingId, direction);
  if (!projection) return '';
  return `<article class="lmo-acquisition-projection" data-acquisition-projection="${escapeHtml(projection.signature)}" style="--before-accent:${safeColor(projection.before.color, '#778096')};--after-accent:${safeColor(projection.after.color)}"><header><div><span>ACQUISITION SIMULATION</span><h3>建筑身份重构预演</h3><p>接管方向已在状态副本中运行；此刻仍未写入 MVU。</p></div><em>${escapeHtml(projection.before.status)} → ${escapeHtml(projection.after.status)}</em></header><div class="lmo-acquisition-grid"><section class="lmo-building-morph"><div><i></i><span>BEFORE</span><strong>${escapeHtml(projection.before.name)}</strong><small>${projection.before.awareness}% 感知</small></div><b>→</b><div><i></i><span>AFTER</span><strong>${escapeHtml(projection.after.name)}</strong><small>${projection.after.awareness}% 感知</small></div></section><section class="lmo-route-morph"><span>PORTFOLIO LINK</span><div><i>H</i><b></b><i>${escapeHtml(projection.after.name.slice(0, 1))}</i></div><p><small>${escapeHtml(projection.network.before)}</small><strong>${escapeHtml(projection.network.after)}</strong></p><div class="lmo-acquisition-deltas"><p><b>${signed(projection.deltas.owned)}</b><small>已接管</small></p><p><b>${signed(projection.deltas.activeRoutes)}</b><small>运营链路</small></p><p><b>${signed(projection.deltas.awareness)}</b><small>感知</small></p><p><b>${signed(projection.deltas.spaces)}</b><small>显露空间</small></p></div></section><aside><span>PLAYABLE OPENINGS</span><strong>${escapeHtml(projection.after.highlight)}</strong><p>${escapeHtml(projection.summary)}</p>${tags([...projection.tags, ...projection.opportunities].slice(0, 6))}${projection.revealedSpaces.length ? `<em>新显露 · ${escapeHtml(projection.revealedSpaces.join(' / '))}</em>` : ''}</aside></div><footer>确认后才会升级版图节点、运营链路、建筑名称、主题与感知状态，并留下接管事件。</footer></article>`;
}
